const reminder = $json;

if (!reminder.reminder_id || !reminder.lease_token) {
  throw new Error("Missing approval reminder ownership");
}

const isEscalation = reminder.reminder_level === "escalation";

const subject = isEscalation
  ? "[ESCALATION] Refund approval awaiting review"
  : "Refund approval requires review";

const message = [
  "TraceOps Approval Notification",
  "",
  isEscalation
    ? "An approval has exceeded its escalation threshold."
    : "A refund approval is awaiting review.",
  "",
  `Approval ID: ${reminder.approval_id}`,
  `Incident ID: ${reminder.incident_id}`,
  `Organization ID: ${reminder.organization_id}`,
  "",
  "Open TraceOps to review and make an authorized decision.",
  "Do not approve or reject refunds by replying to this email."
].join("\n");

return {
  json: {
    ...reminder,
    subject,
    message
  }
};

